WITH scored AS (SELECT *, FIRST_VALUE(credit_limit, TRUE) OVER w_recent AS first_known_credit_limit, ROW_NUMBER() OVER (PARTITION BY country ORDER BY age, id) AS seq_no, NTILE(4) OVER (PARTITION BY city ORDER BY age DESC, id) AS age_bucket FROM customers WINDOW w_recent AS (PARTITION BY country ORDER BY age, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)) SELECT DATE_TRUNC('MONTH', signup_date) AS activity_month, ROUND(SUM(credit_limit) / NULLIF(COUNT(CASE WHEN city = 'Berlin' THEN 1 END), 0), 2) AS credit_limit_per_berlin, COUNT(*) FILTER (WHERE segment = 'Corporate') AS corporate_rows, APPROX_PERCENTILE(age_bucket, ARRAY(0.25, 0.5, 0.75)) AS age_bucket_quartiles FROM scored GROUP BY DATE_TRUNC('MONTH', signup_date);
